import { Component } from '@angular/core';

@Component({
  selector: 'app-home',
  templateUrl: './home.component.html',
  styleUrls: ['./home.component.css']
})
export class HomeComponent {
  popupAberto = false;
  cotacao = {
    nome: '',
    email: '',
    tipo: ''
  };

  constructor() { }

  // ngOnInit não utilizado

  abrirCotacao() {
    this.popupAberto = true;
  }

  fecharCotacao() {
    this.popupAberto = false;
    this.cotacao = { nome: '', email: '', tipo: '' };
  }

  enviarCotacao() {
    // Aqui você pode integrar com backend ou exibir mensagem de sucesso
    alert('Cotação enviada com sucesso!');
    this.fecharCotacao();
  }
}
<nav class="navbar navbar-expand-lg navbar-light bg-white shadow-sm mb-4">
  <div class="container-fluid">
    <a class="navbar-brand fw-bold text-primary" style="font-size:1.7rem;" href="#">
      <img src="assets/logo-prover.png" alt="Prover Seguros" style="height:40px;vertical-align:middle;margin-right:10px;">
    </a>
    <button class="navbar-toggler" type="button" data-bs-toggle="collapse" data-bs-target="#navbarNav" aria-controls="navbarNav" aria-expanded="false" aria-label="Toggle navigation">
      <span class="navbar-toggler-icon"></span>
    </button>
    <div class="collapse navbar-collapse" id="navbarNav">
      <ul class="navbar-nav ms-auto">
        <li class="nav-item">
          <a class="nav-link active" aria-current="page" href="#">Início</a>
        </li>
        <li class="nav-item">
          <a class="nav-link" href="#">Sobre</a>
        </li>
        <li class="nav-item">
          <a class="nav-link" href="#">Produtos</a>
        </li>
        <li class="nav-item">
          <a class="nav-link" href="#">Contato</a>
        </li>
        <li class="nav-item">
          <button class="btn btn-outline-primary ms-3" routerLink="/login">Área Administrativa</button>
        </li>
      </ul>
    </div>
  </div>
</nav>
<section class="hero bg-light py-5 mb-4 border-bottom">
  <div class="container">
    <div class="row align-items-center">
      <div class="col-md-7">
        <h1 class="display-4 fw-bold text-primary mb-3">Proteja o que importa com a <span class="text-dark">Prover Seguros</span></h1>
        <p class="lead text-secondary mb-4">Soluções completas em seguros para sua família, empresa e patrimônio. Atendimento consultivo, confiança e tradição.</p>
  <button class="btn btn-primary btn-lg" routerLink="/cotacao">Solicitar Cotação</button>
      </div>
      <div class="col-md-5 d-none d-md-block">
        <img src="assets/hero-seguro.png" alt="Seguros" class="img-fluid rounded shadow-sm">
      </div>
    </div>
  </div>
</section>
